 const createProduct=async(e:React.FormEvent)=>{e.preventDefault();setError('');const specs:any={};for(const entry of createProductSpecEntries){const key=entry.key.trim();const value=entry.value.trim();if(!key&&!value)continue;if(!key||!value){setError('Please fill in both the specification name and its details, or remove the empty row.');return;}if(Object.prototype.hasOwnProperty.call(specs,key)){setError('Duplicate specification name: '+key);return;}specs[key]=value;}if(productImageFiles.length>6){setError('A product can have up to 6 photos.');return;}for(const file of productImageFiles){if(file.size>5242880||!['image/png','image/jpeg','image/webp'].includes(file.type)){setError('Each product image must be PNG, JPG or WebP and no larger than 5MB.');return;}}setProductSaving(true);const{data:created,error:createError}=await supabase.from('products').insert({name:name.trim(),sku:sku.trim(),price_myr:Number(price),stock_quantity:Number(stock),weight_grams:Number(weight),description,condition,color,specifications:specs,is_published:false,inventory_mode:inventoryMode,category_id:createCategoryIds[0]||null}).select('id').single();if(createError||!created){setError(createError?.message||'Product could not be created.');setProductSaving(false);return;}if(createCategoryIds.length){const{error:categoryLinkError}=await supabase.from('product_categories').insert(createCategoryIds.map(category_id=>({product_id:created.id,category_id})));if(categoryLinkError){setError('Product was created as an unpublished draft, but categories could not be saved: '+categoryLinkError.message);setProductSaving(false);await loadProducts();return;}}const uploadedPaths:string[]=[];const imageRows=[] as Array<{product_id:string;storage_path:string;alt_text:string;display_order:number;is_primary:boolean}>;for(let i=0;i<productImageFiles.length;i++){const file=productImageFiles[i];const ext=file.type==='image/png'?'png':file.type==='image/jpeg'?'jpg':'webp';const storagePath=created.id+'/'+crypto.randomUUID()+'.'+ext;const{error:uploadError}=await supabase.storage.from('product-images').upload(storagePath,file,{contentType:file.type,upsert:false});if(uploadError){if(uploadedPaths.length)await supabase.storage.from('product-images').remove(uploadedPaths);setError('Product was created as an unpublished draft, but image upload failed: '+uploadError.message);setProductSaving(false);await loadProducts();return;}uploadedPaths.push(storagePath);imageRows.push({product_id:created.id,storage_path:storagePath,alt_text:name.trim(),display_order:i,is_primary:i===0});}if(imageRows.length){const{error:imageError}=await supabase.from('product_images').insert(imageRows);if(imageError){await supabase.storage.from('product-images').remove(uploadedPaths);setError('Product was created as an unpublished draft, but its image records could not be saved: '+imageError.message);setProductSaving(false);await loadProducts();return;}}nameReset();setProductTab('list');setError(productImageFiles.length?'Product and '+productImageFiles.length+' image(s) created. It remains unpublished until you choose Publish.':'Product created as an unpublished draft.');await loadProducts();setProductSaving(false);};
 function nameReset(){setName('');setSku('');setPrice('');setStock('1');setInventoryMode('single_item');setWeight('0');setDescription('');setCondition('');setColor('');setSpecifications('{}');setCreateProductSpecEntries([]);setProductImageFiles([]);setCreateCategoryIds([]);}

 const openEditProduct=async(p:ProductRow)=>{setError('');const[{data:product,error:productError},{data:images,error:imageError}]=await Promise.all([supabase.from('products').select('*').eq('id',p.id).single(),supabase.from('product_images').select('*').eq('product_id',p.id).order('display_order',{ascending:true})]);if(productError||!product){setError(productError?.message||'Unable to load product.');return;}if(imageError){setError(imageError.message);return;}setEditingProduct(product);setEditProductForm({name:product.name||'',sku:product.sku||'',price_myr:String(product.price_myr??''),weight_grams:String(product.weight_grams??0),description:product.description||'',condition:product.condition||'',color:product.color||'',specifications:'{}'});setEditProductSpecEntries(Object.entries(product.specifications&&typeof product.specifications==='object'&&!Array.isArray(product.specifications)?product.specifications:{}).map(([key,value])=>({key,value:typeof value==='string'?value:JSON.stringify(value)})));setEditProductImages((images||[]).map((img:any)=>({...img,public_url:supabase.storage.from('product-images').getPublicUrl(img.storage_path).data.publicUrl})));const{data:categoryLinks,error:categoryLinkError}=await supabase.from('product_categories').select('category_id').eq('product_id',p.id);if(categoryLinkError){setError(categoryLinkError.message);return;}setEditCategoryIds((categoryLinks||[]).map((row:any)=>row.category_id));setEditProductImageFiles([]);};
 const saveProductEdits=async(e:React.FormEvent)=>{e.preventDefault();if(!editingProduct)return;setError('');const specs:any={};for(const entry of editProductSpecEntries){const key=entry.key.trim();if(!key)continue;if(Object.prototype.hasOwnProperty.call(specs,key)){setError('Each specification must have a unique name.');return;}const raw=entry.value.trim();if(raw===''){specs[key]='';continue;}try{specs[key]=JSON.parse(raw);}catch{specs[key]=entry.value;}}if(!editProductForm.name.trim()||!editProductForm.sku.trim()||!Number.isFinite(Number(editProductForm.price_myr))||Number(editProductForm.price_myr)<0||!Number.isInteger(Number(editProductForm.weight_grams))||Number(editProductForm.weight_grams)<0){setError('Please check product name, SKU, price and weight.');return;}if(editProductImages.length+editProductImageFiles.length>6){setError('A product can have up to 6 photos in total. Remove an existing photo before adding more.');return;}for(const file of editProductImageFiles){if(file.size>5242880||!['image/png','image/jpeg','image/webp'].includes(file.type)){setError('Each product image must be PNG, JPG or WebP and no larger than 5MB.');return;}}setEditProductSaving(true);const{error:updateError}=await supabase.from('products').update({name:editProductForm.name.trim(),sku:editProductForm.sku.trim(),price_myr:Number(editProductForm.price_myr),weight_grams:Number(editProductForm.weight_grams),description:editProductForm.description,condition:editProductForm.condition,color:editProductForm.color,specifications:specs,category_id:editCategoryIds[0]||null}).eq('id',editingProduct.id);if(updateError){setError(updateError.message);setEditProductSaving(false);return;}const{error:clearCategoryError}=await supabase.from('product_categories').delete().eq('product_id',editingProduct.id);if(clearCategoryError){setError('Product details saved, but categories could not be updated: '+clearCategoryError.message);setEditProductSaving(false);return;}if(editCategoryIds.length){const{error:saveCategoryError}=await supabase.from('product_categories').insert(editCategoryIds.map(category_id=>({product_id:editingProduct.id,category_id})));if(saveCategoryError){setError('Product details saved, but categories could not be updated: '+saveCategoryError.message);setEditProductSaving(false);return;}}if(editProductImageFiles.length)await uploadProductImages({...editingProduct,name:editProductForm.name.trim()},editProductImageFiles);const{data:images,error:imageError}=await supabase.from('product_images').select('*').eq('product_id',editingProduct.id).order('display_order',{ascending:true});if(imageError)setError('Product details saved, but photos could not be refreshed: '+imageError.message);else setEditProductImages((images||[]).map((img:any)=>({...img,public_url:supabase.storage.from('product-images').getPublicUrl(img.storage_path).data.publicUrl})));setEditProductImageFiles([]);if(!imageError)setError('Product information saved successfully.');await loadProducts();setEditProductSaving(false);};
 const removeProductPhoto=async(image:any)=>{if(!editingProduct||!window.confirm('Remove this product photo?'))return;const{error:rowError}=await supabase.from('product_images').delete().eq('id',image.id).eq('product_id',editingProduct.id);if(rowError){setError(rowError.message);return;}const{error:storageError}=await supabase.storage.from('product-images').remove([image.storage_path]);if(storageError)setError('Photo record removed, but the storage file could not be deleted: '+storageError.message);const{data:remaining,error}=await supabase.from('product_images').select('*').eq('product_id',editingProduct.id).order('display_order',{ascending:true});if(error){setError(error.message);return;}if(remaining?.length&&!remaining.some((img:any)=>img.is_primary)){await supabase.from('product_images').update({is_primary:true}).eq('id',remaining[0].id);}setEditProductImages((remaining||[]).map((img:any)=>({...img,public_url:supabase.storage.from('product-images').getPublicUrl(img.storage_path).data.publicUrl,is_primary:img.is_primary||(!remaining.some((x:any)=>x.is_primary)&&img.id===remaining[0]?.id)})));setError('Product photo removed.');};
 const setPrimaryProductPhoto=async(image:any)=>{if(!editingProduct)return;const{error:clearError}=await supabase.from('product_images').update({is_primary:false}).eq('product_id',editingProduct.id);if(clearError){setError(clearError.message);return;}const{error}=await supabase.from('product_images').update({is_primary:true}).eq('id',image.id).eq('product_id',editingProduct.id);if(error){setError(error.message);return;}setEditProductImages(current=>current.map(img=>({...img,is_primary:img.id===image.id})));setError('Main product photo updated.');};
 const pasteEditProductImages=(event:React.ClipboardEvent<HTMLDivElement>)=>{const items=Array.from(event.clipboardData.items);const files=items.filter(item=>item.kind==='file'&&item.type.startsWith('image/')).map(item=>item.getAsFile()).filter((file):file is File=>!!file&&['image/jpeg','image/png','image/webp'].includes(file.type));if(!files.length){setError('Copy a JPG, PNG or WebP image, click this area, then press Ctrl+V.');return;}event.preventDefault();setEditProductImageFiles(current=>{const remaining=Math.max(0,6-editProductImages.length-current.length);if(files.length>remaining)setError('A product can have up to 6 photos. Only '+remaining+' pasted photo(s) were added.');return [...current,...files.slice(0,remaining)];});};
 const changeInventoryMode=async(p:ProductRow)=>{const nextMode=p.inventory_mode==='single_item'?'multiple':'single_item';if(nextMode==='single_item'&&p.stock_quantity>1){setError('Cannot switch to Single-item Inventory while stock is above 1. Reduce stock to 1 or less first.');return;}if(p.reserved_quantity>0){setError('Cannot change inventory mode while stock is reserved for existing orders.');return;}if(!window.confirm('Change '+p.name+' to '+(nextMode==='single_item'?'Single-item Inventory (maximum 1 unit)':'Multiple-item Inventory (no one-unit limit)')+'?'))return;const{error}=await supabase.from('products').update({inventory_mode:nextMode}).eq('id',p.id);if(error)setError(error.message);else{setError('Inventory mode updated to '+(nextMode==='single_item'?'Single-item':'Multiple-item')+'.');await loadProducts();}};
 const togglePublish=async(p:ProductRow)=>{const{error}=await supabase.from('products').update({is_published:!p.is_published}).eq('id',p.id);if(error)setError(error.message);else await loadProducts();};
 const archive=async(p:ProductRow)=>{const reason=window.prompt('Enter archive reason:');if(!reason?.trim())return;const{error}=await supabase.rpc('archive_product',{p_product_id:p.id,p_reason:reason});if(error)setError(error.message);else await loadProducts();};
 const restore=async(p:ProductRow)=>{const reason=window.prompt('Enter restore reason:');if(!reason?.trim())return;const{error}=await supabase.rpc('restore_product',{p_product_id:p.id,p_reason:reason});if(error)setError(error.message);else await loadProducts();};
 const addVariant=async(p:ProductRow)=>{const vName=window.prompt('Option name (e.g. Size / Model):');if(!vName?.trim())return;const vValue=window.prompt('Option value:');if(!vValue?.trim())return;const vSku=window.prompt('Unique SKU:');if(!vSku?.trim())return;const vPrice=Number(window.prompt('Variant price in MYR:','0'));const vWeight=Number(window.prompt('Variant weight in grams:','0'));const vStock=Number(window.prompt('Variant stock quantity:','1'));if(!Number.isFinite(vPrice)||vPrice<0||!Number.isInteger(vWeight)||vWeight<0||!Number.isInteger(vStock)||vStock<0){setError('Invalid variant price, weight or stock.');return;}if(p.stock_quantity>0||p.reserved_quantity>0){setError('Set product-level stock to zero before adding variants.');return;}const{error:modeError}=await supabase.rpc('enable_product_variants',{p_product_id:p.id});if(modeError){setError(modeError.message);return;}const{error}=await supabase.from('product_variants').insert({product_id:p.id,variant_name:vName.trim(),variant_value:vValue.trim(),sku:vSku.trim(),price_myr:vPrice,weight_grams:vWeight,stock_quantity:vStock,reserved_quantity:0,is_active:true});if(error)setError(error.message);else setError('Variant added successfully.');};
 const reviewCancel=async(id:string,decision:'approved'|'rejected')=>{const note=window.prompt('Admin note / reason (required for audit):');if(!note?.trim())return;const{error}=await supabase.rpc('review_order_cancellation',{p_request_id:id,p_decision:decision,p_admin_note:note});if(error)setError(error.message);else await loadOrders();};
 const loadOrderDetail=async(orderId:string)=>{setOrderDetailLoading(true);setSelectedOrderDetail(null);const results=await Promise.all([supabase.from('orders').select('*').eq('id',orderId).single(),supabase.from('order_items').select('*').eq('order_id',orderId).order('created_at'),can('payments.review')?supabase.from('payment_proofs').select('id,storage_path,original_filename,mime_type,file_size,submission_number,review_status,reviewed_at,review_note,created_at').eq('order_id',orderId).order('created_at',{ascending:false}):Promise.resolve({data:[],error:null}),supabase.from('order_status_history').select('id,old_status,new_status,reason,changed_by,created_at').eq('order_id',orderId).order('created_at',{ascending:false}),supabase.from('shipments').select('id,shipment_number,carrier_name,tracking_number,tracking_url,shipment_status,shipped_at,delivered_at,created_at,shipment_items(id,order_item_id,quantity)').eq('order_id',orderId).order('created_at',{ascending:false})]);const failed=results.find(r=>r.error);if(failed){setError(failed.error?.message||'Unable to load order details.');setOrderDetailLoading(false);return;}const order=results[0].data;let profile=null;const profileResult=await supabase.from('profiles').select('display_name,phone,whatsapp').eq('id',order.user_id).maybeSingle();if(!profileResult.error)profile=profileResult.data;const items=await Promise.all((results[1].data||[]).map(async(item:any)=>{const image=item.product_image;if(!image||/^https?:\/\//i.test(image)||image.startsWith('data:'))return item;const{data:imageData}=supabase.storage.from('product-images').getPublicUrl(image);return {...item,product_image:imageData?.publicUrl||null};}));setSelectedOrderDetail({order,items,proofs:results[2].data||[],history:results[3].data||[],shipments:results[4].data||[],profile});setOrderDetailLoading(false);};
 const printWarehouseDispatch=()=>{if(!selectedOrderDetail)return;const{order,items}=selectedOrderDetail;const w=window.open('','_blank','width=900,height=700');if(!w){setError('Please allow pop-ups to print the warehouse dispatch sheet.');return;}const esc=(v:any)=>String(v??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch] as string));const addr=order.shipping_address&&typeof order.shipping_address==='object'?Object.entries(order.shipping_address).map(([k,v])=>'<div><b>'+esc(k)+':</b> '+esc(v)+'</div>').join(''):'<div>'+esc(order.shipping_address)+'</div>';const rows=items.map((it:any)=>'<tr><td>'+esc(it.product_name)+'</td><td>'+esc(it.variant_snapshot?JSON.stringify(it.variant_snapshot):'—')+'</td><td>'+esc(it.quantity)+'</td></tr>').join('');w.document.write('<!doctype html><html><head><title>Warehouse Dispatch '+esc(order.order_number)+'</title><style>body{font:14px Arial,sans-serif;margin:32px;color:#111}h1{font-size:22px}h2{font-size:16px;margin:24px 0 8px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px}.panel{border:1px solid #999;padding:12px;margin:12px 0}table{width:100%;border-collapse:collapse;margin-top:8px}th,td{border:1px solid #999;padding:9px;text-align:left}th{background:#eee}.blank{height:30px;border-bottom:1px solid #777}.small{color:#555;font-size:12px}@media print{button{display:none}body{margin:12mm}}</style></head><body><h1>WAREHOUSE DISPATCH INFORMATION</h1><p><b>Order:</b> '+esc(order.order_number)+' &nbsp; <b>Order Date:</b> '+esc(new Date(order.created_at).toLocaleString())+'</p><div class="meta"><div class="panel"><h2>SHIP TO</h2><b>'+esc(order.recipient_name)+'</b><p>'+esc(order.recipient_phone)+'</p>'+addr+'</div><div class="panel"><h2>PARCEL / AWB — WAREHOUSE USE</h2><p>Carrier / courier</p><div class="blank"></div><p>Actual AWB / tracking number</p><div class="blank"></div><p>Parcel / bag reference</p><div class="blank"></div></div></div><h2>ITEMS TO PACK</h2><table><thead><tr><th>Product</th><th>Variant / specifications</th><th>Quantity</th></tr></thead><tbody>'+rows+'</tbody></table><div class="panel"><b>Warehouse packing notes</b><div class="blank"></div><div class="blank"></div></div><p class="small">This is an internal dispatch instruction only. It is not a carrier-issued AWB or shipping label. Warehouse staff must generate and print the official carrier AWB using the carrier&#39;s own system.</p><button onclick="window.print()">Print dispatch sheet</button></body></html>');w.document.close();w.focus();};
 const createShipment=async(o:OrderRow)=>{const shipmentNumber=window.prompt('Actual AWB / shipment number returned by the warehouse:');if(!shipmentNumber?.trim())return;const carrier=window.prompt('Carrier name:')||'';const tracking=window.prompt('Tracking number (if different from AWB):')||'';const trackingUrl=window.prompt('Tracking URL (optional):')||'';const lines=[] as Array<{order_item_id:string;quantity:number}>;for(const item of o.order_items||[]){const raw=window.prompt('Quantity actually handed to the carrier for '+item.product_name+' (ordered '+item.quantity+', enter 0 to skip):','0');if(raw===null)return;const qty=Number(raw);if(!Number.isInteger(qty)||qty<0||qty>item.quantity){setError('Enter a whole number between 0 and the ordered quantity.');return;}if(qty>0)lines.push({order_item_id:item.id,quantity:qty});}if(!lines.length){setError('Enter at least one item quantity actually dispatched.');return;}if(!window.confirm('Confirm the parcel has physically been handed to the carrier? This records dispatch, consumes the corresponding reserved stock and may mark the order Shipped.'))return;const{error}=await supabase.rpc('create_shipment',{p_order_id:o.id,p_shipment_number:shipmentNumber.trim(),p_carrier:carrier,p_tracking_number:tracking,p_tracking_url:trackingUrl,p_items:lines});if(error)setError(error.message);else{setError('Actual dispatch recorded.');await loadOrders();await loadOrderDetail(o.id);}};
 const executeCancel=async(id:string)=>{const reason=window.prompt('Execution reason (required):');if(!reason?.trim())return;const{error}=await supabase.rpc('execute_order_cancellation',{p_request_id:id,p_reason:reason});if(error)setError(error.message);else await loadOrders();};
 const reviewAddress=async(id:string,decision:'approved'|'rejected')=>{const note=window.prompt('Admin note (required for audit):');if(!note?.trim())return;const{error}=await supabase.rpc('review_shipping_address_change',{p_request_id:id,p_decision:decision,p_admin_note:note});if(error)setError(error.message);else await loadOrders();};
 const review=async(p:ProofRow,decision:'approved'|'rejected')=>{const note=decision==='rejected'?window.prompt('Reason for rejecting this payment proof:'): 'Payment proof approved';if(decision==='rejected'&&!note?.trim())return;const{error}=await supabase.rpc('admin_review_payment',{p_payment_proof_id:p.id,p_decision:decision,p_note:note||''});if(error)setError(error.message);else await loadProofs();};
 const openProof=async(path:string)=>{const{data,error}=await supabase.storage.from('payment-proofs').createSignedUrl(path,60);if(error)setError(error.message);else window.open(data.signedUrl,'_blank','noopener,noreferrer');};
 const uploadProductImages=async(p:ProductRow,files:File[])=>{if(!files.length)return;const{count,error:countError}=await supabase.from('product_images').select('id',{count:'exact',head:true}).eq('product_id',p.id);if(countError){setError(countError.message);return;}const existing=count||0;if(existing+files.length>6){setError('This product already has '+existing+' photo(s). You can add only '+(6-existing)+' more.');return;}for(const file of files){if(file.size>5242880||!['image/jpeg','image/png','image/webp'].includes(file.type)){setError('Each product image must be JPG, PNG or WebP and no larger than 5MB.');return;}}const uploaded:string[]=[];const rows=[] as Array<{product_id:string;storage_path:string;alt_text:string;display_order:number;is_primary:boolean}>;for(let i=0;i<files.length;i++){const file=files[i];const ext=file.type==='image/jpeg'?'jpg':file.type==='image/png'?'png':'webp';const path=p.id+'/'+crypto.randomUUID()+'.'+ext;const{error:upError}=await supabase.storage.from('product-images').upload(path,file,{contentType:file.type,upsert:false});if(upError){if(uploaded.length)await supabase.storage.from('product-images').remove(uploaded);setError('Photo upload failed: '+upError.message);return;}uploaded.push(path);rows.push({product_id:p.id,storage_path:path,alt_text:p.name,display_order:existing+i,is_primary:existing===0&&i===0});}const{error}=await supabase.from('product_images').insert(rows);if(error){await supabase.storage.from('product-images').remove(uploaded);setError(error.message);return;}setError(files.length+' photo(s) uploaded successfully.');};
 const getPastedProductImages=(event:React.ClipboardEvent<HTMLDivElement>)=>{const items=Array.from(event.clipboardData.items);const pasted=items.filter(item=>item.kind==='file'&&item.type.startsWith('image/')).map(item=>item.getAsFile()).filter((file):file is File=>!!file);if(!pasted.length){setError('Copy an image first, click this paste area, then press Ctrl+V.');return [];}event.preventDefault();const supported=pasted.filter(file=>['image/jpeg','image/png','image/webp'].includes(file.type));if(supported.length!==pasted.length)setError('Only JPG, PNG and WebP images can be pasted.');return supported.map((file,index)=>new File([file],file.name||('pasted-product-photo-'+(index+1)+'.'+(file.type==='image/png'?'png':file.type==='image/jpeg'?'jpg':'webp')),{type:file.type}));};
 const pasteNewProductImages=(event:React.ClipboardEvent<HTMLDivElement>)=>{const files=getPastedProductImages(event);if(!files.length)return;setProductImageFiles(current=>{const remaining=Math.max(0,6-current.length);if(files.length>remaining)setError('A product can have up to 6 photos. Only the first '+remaining+' pasted photo(s) were added.');return [...current,...files.slice(0,remaining)];});};
 const pasteExistingProductImages=(event:React.ClipboardEvent<HTMLDivElement>,product:ProductRow)=>{const files=getPastedProductImages(event);if(files.length)void uploadProductImages(product,files);};

 const createZone=async(e:React.FormEvent)=>{e.preventDefault();const{error}=await supabase.from('shipping_zones').insert({zone_name:zoneName.trim(),country_code:zoneCountry.toUpperCase(),region_code:zoneRegion.trim()||null,is_active:true});if(error)setError(error.message);else{setZoneName('');setZoneRegion('');await loadShipping();}};
